issue.body:
Hi, for all!
I need to show and close map in some window widget and expect that after removing all layers, deleting all references to ol3 objects memory will be freed by GC. But I noticed on memory snapshot that they are still in memory.

Can somebody explain is this expected behavior? If so, how can I totally clear all references for CG and free memory after map destruction? I need it because layers in my app have huge number of objects, not killed objects consume all memory after several create/destroy operations.

I wrote simple test example, after N add/remove buttons click you will see on memory snapshot that here N ol.Map and N * 1000 ol.Feature leaked instances. they are retained by event listeners
```
<!DOCTYPE html>
<html>
<head lang="en">
    <meta charset="UTF-8">
    <title>ol test</title>

    <style>
        html, body { height : 100%; }

        #buttons {
            position : absolute;
            left     : 0;
            top      : 0;
        }
    </style>

    <script src="ol-debug.js"></script>
</head>
<body>
<div id="map" style="height: 100%"></div>
<div id="buttons">
    <button id="add">add</button>
    <button id="remove">Remove</button>
</div>

<script>
    var map, vector, raster;

    document.getElementById("add").addEventListener("click", function(e) {
        e.preventDefault();

        addMap();
    });

    document.getElementById("remove").addEventListener("click", function(e) {
        e.preventDefault();

        removeMap();
    });

    function addMap() {
        vector = new ol.layer.Vector({
            source: new ol.source.Vector()
        });

        var count = 1000;
        var e = 4500000;

        for (var i = 0; i < count; ++i) {
            var coordinates = [2 * e * Math.random() - e, 2 * e * Math.random() - e];
            var feature = new ol.Feature({
                id: i,
                geometry: new ol.geom.Point(coordinates)
            });

            feature.setId(i);

            vector.getSource().addFeature(feature);
        }

        raster = new ol.layer.Tile({
            source: new ol.source.MapQuest({ layer: 'sat' })
        });

        map = new ol.Map({
            layers: [raster, vector],
            target: 'map',
            view: new ol.View({
                center: [0, 0],
                zoom: 2
            })
        });
    }

    function removeMap() {
        vector.getSource().clear();
        map.removeLayer(vector);
        map.removeLayer(raster);
        vector = null;
        raster = null;  

        map.setTarget(null);
        map = null;
    }
</script>
</body>
</html>
```
